for (let i = 0; i < n; i++) { pts.push(addpoint(0, [0, (i + 1) * r, i * d])); pts.push(addpoint(0, [0, (i + 1) * r, (i + 1) * d])); }
pts.push(addpoint(0, [0, 0, n * d]));
