const n = Math.round(steps), r = rise, d = run, L = n * d, k = r / d;
const z0 = Math.max(0, L - (n * r - 0.3) / k);
const P = [[0, 0, 0], [0, r, 0], [0, n * r, Math.max(0, L - d)], [0, n * r, L], [0, Math.max(0, n * r - 0.3), L], [0, 0, z0]];
const out = [];
for (const p of P) if (!out.length || distance(out[out.length - 1], p) > 1e-6) out.push(p);
if (out.length > 3 && distance(out[0], out[out.length - 1]) <= 1e-6) out.pop();
addprim(0, 'poly', out.map((p) => addpoint(0, p)));

